/**
 * Group-comparison tests — the statistics a clustering has to answer to.
 *
 * These were written in carmnote-htna-pro/lib/covariates.js and pinned against R to 8+
 * decimals (aov, kruskal.test, chisq.test, pairwise.t.test, p.adjust) over 119 randomly
 * shaped datasets. They live in the ENGINE now, for the same reason prepareLong does: a
 * statistic that three notebooks each implement is a statistic that three notebooks each get
 * subtly differently, and only one of them is checked.
 *
 * Pinned by tests/group-tests.test.ts. R ground truth is generated by tests/fixtures/.
 */
import { stdResiduals } from '../analysis/compare.js';


export interface AnovaResult { F: number; df1: number; df2: number; p: number; eta2: number }
export interface KruskalResult { H: number; df: number; p: number }
export interface ChisqResult {
  X2: number; df: number; p: number; cramerV: number; n: number;
  expectedMin: number; residuals: number[][]; dropped: boolean;
}
export interface WelchPair { a: string; b: string; diff: number; t: number; df: number; p: number; pAdj?: number }
export interface ChisqPair { a: string; b: string; X2: number; df: number; p: number; cramerV: number; pAdj?: number }

function logGamma(x: number): number {
  const c: number[] = [76.18009172947146, -86.50532032941677, 24.01409824083091,
    -1.231739572450155, 0.1208650973866179e-2, -0.5395239384953e-5];
  let y = x, tmp = x + 5.5;
  tmp -= (x + 0.5) * Math.log(tmp);
  let ser = 1.000000000190015;
  for (let j = 0; j < 6; j++) ser += c[j]! / ++y;
  return -tmp + Math.log(2.5066282746310005 * ser / x);
}

function betacf(a: number, b: number, x: number): number {
  const FPMIN = 1e-300, EPS = 3e-16;
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - (qab * x) / qap;
  if (Math.abs(d) < FPMIN) d = FPMIN;
  d = 1 / d;
  let h = d;
  for (let m = 1; m <= 300; m++) {
    const m2 = 2 * m;
    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) < FPMIN) d = FPMIN;
    c = 1 + aa / c; if (Math.abs(c) < FPMIN) c = FPMIN;
    d = 1 / d; h *= d * c;
    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if (Math.abs(d) < FPMIN) d = FPMIN;
    c = 1 + aa / c; if (Math.abs(c) < FPMIN) c = FPMIN;
    d = 1 / d;
    const del = d * c;
    h *= del;
    if (Math.abs(del - 1) < EPS) break;
  }
  return h;
}

/** Regularized incomplete beta I_x(a,b). */
function ibeta(a: number, b: number, x: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const bt = Math.exp(logGamma(a + b) - logGamma(a) - logGamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  return x < (a + 1) / (a + b + 2) ? (bt * betacf(a, b, x)) / a : 1 - (bt * betacf(b, a, 1 - x)) / b;
}

/** Upper tail of F(df1, df2) — the ANOVA p-value. */
export function pf(f: number, df1: number, df2: number): number {
  if (!(f > 0) || !isFinite(f)) return 1;
  return ibeta(df2 / 2, df1 / 2, df2 / (df2 + df1 * f));
}

/** Two-sided p of Student's t on df. */
export function pt2(t: number, df: number): number {
  if (!isFinite(t) || !(df > 0)) return 1;
  return ibeta(df / 2, 0.5, df / (df + t * t));
}

/** Regularized lower incomplete gamma P(a,x) — series below the crossover, continued
 *  fraction above it, which is where each converges fast. */
function gammaP(a: number, x: number): number {
  if (x <= 0) return 0;
  if (x < a + 1) {                       // series
    let ap = a, sum = 1 / a, del = sum;
    for (let n = 0; n < 500; n++) {
      ap += 1; del *= x / ap; sum += del;
      if (Math.abs(del) < Math.abs(sum) * 3e-16) break;
    }
    return sum * Math.exp(-x + a * Math.log(x) - logGamma(a));
  }
  // continued fraction for Q(a,x) = 1 - P(a,x)
  const FPMIN = 1e-300;
  let b = x + 1 - a, c = 1 / FPMIN, d = 1 / b, h = d;
  for (let i = 1; i <= 500; i++) {
    const an = -i * (i - a);
    b += 2;
    d = an * d + b; if (Math.abs(d) < FPMIN) d = FPMIN;
    c = b + an / c; if (Math.abs(c) < FPMIN) c = FPMIN;
    d = 1 / d;
    const del = d * c;
    h *= del;
    if (Math.abs(del - 1) < 3e-16) break;
  }
  return 1 - Math.exp(-x + a * Math.log(x) - logGamma(a)) * h;
}

/** Upper tail of chi-square on df — the p-value of a chi-square / Kruskal–Wallis statistic. */
export function pchisq(q: number, df: number): number {
  if (!(q > 0) || !(df > 0)) return 1;
  return 1 - gammaP(df / 2, q / 2);
}

// ── numeric covariate: ANOVA + Kruskal–Wallis ───────────────────────────────

const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / (a.length || 1);
const varOf = (a: number[]): number => { const m = mean(a); return a.reduce((s, v) => s + (v - m) * (v - m), 0) / Math.max(1, a.length - 1); };

/**
 * One-way ANOVA across k groups.
 * eta^2 = SS_between / SS_total — the proportion of the covariate's variance the clustering
 * accounts for. Reported ALWAYS, next to p: with 30 sessions a "significant" difference can
 * be trivial and a large one can miss significance, and only the effect size says which.
 */
export function anova(groups: number[][]): AnovaResult | null {
  const gs = groups.filter((g) => g.length > 0);
  const k = gs.length;
  const all = gs.flat();
  const N = all.length;
  if (k < 2 || N <= k) return null;
  const grand = mean(all);
  const ssb = gs.reduce((s, g) => { const d = mean(g) - grand; return s + g.length * d * d; }, 0);
  const ssw = gs.reduce((s, g) => { const m = mean(g); return s + g.reduce((t, v) => t + (v - m) * (v - m), 0); }, 0);
  const df1 = k - 1, df2 = N - k;
  const msb = ssb / df1, msw = ssw / df2;
  const F = msw > 0 ? msb / msw : Infinity;
  const sst = ssb + ssw;
  return { F, df1, df2, p: pf(F, df1, df2), eta2: sst > 0 ? ssb / sst : 0 };
}

/** Kruskal–Wallis H, tie-corrected (R's kruskal.test). */
export function kruskal(groups: number[][]): KruskalResult | null {
  const gs = groups.filter((g) => g.length > 0);
  const k = gs.length;
  if (k < 2) return null;
  const all: { v: number; gi: number }[] = [];
  gs.forEach((g, gi) => g.forEach((v) => all.push({ v, gi })));
  const N = all.length;
  if (N <= k) return null;
  all.sort((a, b) => a.v - b.v);

  // Mid-ranks for ties, and the tie-correction term R applies.
  const ranks: number[] = new Array(N);
  let ties = 0;
  for (let i = 0; i < N;) {
    let j = i;
    while (j + 1 < N && all[j + 1]!.v === all[i]!.v) j++;
    const r = (i + j + 2) / 2;             // 1-based mid-rank
    for (let t = i; t <= j; t++) ranks[t]! = r;
    const m = j - i + 1;
    if (m > 1) ties += m * m * m - m;
    i = j + 1;
  }
  const sums = new Array(k).fill(0), ns = new Array(k).fill(0);
  all.forEach((o, i) => { sums[o.gi]! += ranks[i]!; ns[o.gi]!++; });

  let H = 0;
  for (let g = 0; g < k; g++) H += (sums[g]! * sums[g]!) / ns[g]!;
  H = (12 / (N * (N + 1))) * H - 3 * (N + 1);
  const corr = 1 - ties / (N * N * N - N);
  if (corr > 0) H /= corr;
  const df = k - 1;
  return { H, df, p: pchisq(H, df) };
}

// ── categorical covariate: chi-square + Cramér's V + residuals ──────────────

/**
 * Chi-square of independence on a cluster × level table, with Cramér's V and the per-cell
 * standardized adjusted residuals (via `stdres`, which the caller passes in from tnaj so
 * there is exactly one definition of a residual in this notebook).
 *
 * `expectedMin` rides along on purpose: the chi-square approximation needs expected counts
 * of ~5, cluster × covariate tables are small, and R warns about this. Reporting the p while
 * silently swallowing R's warning would be the notebook lying by omission.
 */
export function chisqTest(table: number[][], stdres: (t: number[][]) => number[][] = stdResiduals): ChisqResult | null {
  if (!table.length || !table[0]!.length) return null;

  // EMPTY MARGINS FIRST. A row or column that is entirely zero has expected count 0 in every
  // cell — R's chisq.test returns NaN for such a table, and the naive fix (skip the zero
  // cells) is worse than NaN: it sums the statistic over the surviving cells while still
  // taking df from the FULL dimensions, so the statistic is right and the p-value is
  // computed on too many degrees of freedom. Silently conservative, silently wrong.
  //
  // This bites on the PAIRWISE tables, not the omnibus one: a category present in the data
  // can easily be absent from both clusters of one pair. A level nobody in either group
  // chose carries no information about how they differ, so it is dropped and df comes from
  // the reduced table — defined, correct, and what any analyst would do by hand.
  // (Found by the 119-dataset Monte Carlo sweep; the single fixture never produced one.)
  const keepR = table.map((r) => r.reduce((s, v) => s + v, 0) > 0);
  const keepC = table[0]!.map((_, j) => table.reduce((s, r) => s + r[j]!, 0) > 0);
  const t = table.filter((_, i) => keepR[i]!).map((r) => r.filter((_, j) => keepC[j]!));

  const rows = t.length, cols = rows ? t[0]!.length : 0;
  if (rows < 2 || cols < 2) return null;
  const rowT = t.map((r) => r.reduce((s, v) => s + v, 0));
  const colT = Array.from({ length: cols }, (_, j) => t.reduce((s, r) => s + r[j]!, 0));
  const N = rowT.reduce((s, v) => s + v, 0);
  if (!N) return null;

  let X2 = 0, expectedMin = Infinity;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      const e = (rowT[i]! * colT[j]!) / N;
      if (e < expectedMin) expectedMin = e;
      const d = t[i]![j]! - e;
      X2 += (d * d) / e;
    }
  }
  const df = (rows - 1) * (cols - 1);
  const V = Math.sqrt(X2 / (N * (Math.min(rows, cols) - 1)));
  return { X2, df, p: pchisq(X2, df), cramerV: V, n: N, expectedMin, residuals: stdres(t), dropped: cols !== table[0]!.length || rows !== table.length };
}

// ── post-hoc: WHICH clusters differ ─────────────────────────────────────────

/**
 * Pairwise Welch t-tests between clusters, multiplicity-adjusted.
 *
 * NOT Games–Howell, and the difference is worth stating. Games–Howell is the Welch t with a
 * STUDENTIZED-RANGE adjustment (ptukey), which the engine does not implement; this uses the
 * identical Welch t statistic and df, and adjusts with Holm (or BH) instead. Holm is valid
 * and slightly more conservative than the studentized range, so the risk it carries is a
 * missed difference, never a fabricated one. It is exactly R's
 * `pairwise.t.test(x, g, pool.sd = FALSE, p.adjust.method = "holm")`, which is what the
 * comparison is pinned against.
 */
export function pairwiseWelch(names: string[], groups: number[][], adjust: string, pAdjust: (p: number[], m: string) => number[]): WelchPair[] {
  const out: WelchPair[] = [];
  for (let i = 0; i < groups.length - 1; i++) {
    for (let j = i + 1; j < groups.length; j++) {
      const x = groups[i]!, y = groups[j]!;
      if (x.length < 2 || y.length < 2) continue;
      const vx = varOf(x) / x.length, vy = varOf(y) / y.length;
      const se = Math.sqrt(vx + vy);
      const t = se > 0 ? (mean(x) - mean(y)) / se : 0;
      const df = se > 0
        ? ((vx + vy) * (vx + vy)) / ((vx * vx) / (x.length - 1) + (vy * vy) / (y.length - 1))
        : 1;
      out.push({ a: names[i]!, b: names[j]!, diff: mean(x) - mean(y), t, df, p: pt2(t, df) });
    }
  }
  const adj = pAdjust(out.map((r) => r.p), adjust || 'holm');
  out.forEach((r, i) => { r.pAdj = adj[i]!; });
  return out;
}

/** Pairwise chi-square between clusters (each a 2 × levels sub-table), multiplicity-adjusted. */
export function pairwiseChisq(names: string[], table: number[][], adjust: string, pAdjust: (p: number[], m: string) => number[], stdres: (t: number[][]) => number[][] = stdResiduals): ChisqPair[] {
  const out: ChisqPair[] = [];
  for (let i = 0; i < table.length - 1; i++) {
    for (let j = i + 1; j < table.length; j++) {
      const sub = chisqTest([table[i]!, table[j]!], stdres);
      if (!sub) continue;
      out.push({ a: names[i]!, b: names[j]!, X2: sub.X2, df: sub.df, p: sub.p, cramerV: sub.cramerV });
    }
  }
  const adj = pAdjust(out.map((r) => r.p), adjust || 'BH');
  out.forEach((r, i) => { r.pAdj = adj[i]!; });
  return out;
}

