/**
 * Reliability analysis: split-half comparison of TNA weight matrices.
 * Port of Desktop analysis/reliability.ts.
 *
 * All 22 metrics match R's implementation exactly. Key behaviour notes:
 *  - All vector-level metrics operate on the FULL n×n weight matrix
 *    (including diagonal), flattened column-major (same as R as.vector()).
 *  - Rank Agreement uses matrix row-differences, matching R's diff(matrix).
 *  - RV coefficient uses column-centred tcrossprod formula.
 *  - Distance correlation matches R's biased estimator (can be negative).
 */
import type { TNA, SequenceData } from '../core/types.js';
import { tna, ftna, ctna, atna } from '../core/model.js';
import { SeededRNG } from '../core/rng.js';
import { computeTransitions3D, computeWeightsFrom3D } from '../core/transitions.js';
import { spearmanCorrArr, kendallTau, distanceCorr, rvCoefficient } from '../stats/correlation.js';

// ── Metric definitions ───────────────────────────────────────────────────────

export interface MetricDef {
  key: string;
  label: string;
  category: 'Deviations' | 'Correlations' | 'Dissimilarities' | 'Similarities' | 'Pattern';
}

export const RELIABILITY_METRICS: MetricDef[] = [
  { key: 'mad',        label: 'Mean Abs. Diff.',   category: 'Deviations' },
  { key: 'median_ad',  label: 'Median Abs. Diff.', category: 'Deviations' },
  { key: 'rmsd',       label: 'RMS Diff.',          category: 'Deviations' },
  { key: 'max_ad',     label: 'Max Abs. Diff.',     category: 'Deviations' },
  { key: 'rel_mad',    label: 'Rel. MAD',           category: 'Deviations' },
  { key: 'cv_ratio',   label: 'CV Ratio',           category: 'Deviations' },
  { key: 'pearson',    label: 'Pearson',            category: 'Correlations' },
  { key: 'spearman',   label: 'Spearman',           category: 'Correlations' },
  { key: 'kendall',    label: 'Kendall',            category: 'Correlations' },
  { key: 'dcor',       label: 'Distance Corr.',     category: 'Correlations' },
  { key: 'euclidean',  label: 'Euclidean',          category: 'Dissimilarities' },
  { key: 'manhattan',  label: 'Manhattan',          category: 'Dissimilarities' },
  { key: 'canberra',   label: 'Canberra',           category: 'Dissimilarities' },
  { key: 'braycurtis', label: 'Bray-Curtis',        category: 'Dissimilarities' },
  { key: 'frobenius',  label: 'Frobenius',          category: 'Dissimilarities' },
  { key: 'cosine',     label: 'Cosine',             category: 'Similarities' },
  { key: 'jaccard',    label: 'Jaccard',            category: 'Similarities' },
  { key: 'dice',       label: 'Dice',               category: 'Similarities' },
  { key: 'overlap',    label: 'Overlap',            category: 'Similarities' },
  { key: 'rv',         label: 'RV',                 category: 'Similarities' },
  { key: 'rank_agree', label: 'Rank Agreement',     category: 'Pattern' },
  { key: 'sign_agree', label: 'Sign Agreement',     category: 'Pattern' },
];

// ── Result types ─────────────────────────────────────────────────────────────

export interface ReliabilityMetricSummary {
  metric: string;
  category: string;
  mean: number;
  sd: number;
  median: number;
  min: number;
  max: number;
  q25: number;
  q75: number;
}

export interface ReliabilityResult {
  iterations: Record<string, number[]>;
  summary: ReliabilityMetricSummary[];
  iter: number;
  split: number;
  modelType: string;
}

// ── Internal math helpers ────────────────────────────────────────────────────

function arrMean(a: number[]): number {
  if (a.length === 0) return NaN;
  return a.reduce((s, v) => s + v, 0) / a.length;
}

function arrStd(a: number[], ddof = 1): number {
  if (a.length < ddof + 1) return NaN;
  const m = arrMean(a);
  const variance = a.reduce((s, v) => s + (v - m) ** 2, 0) / (a.length - ddof);
  return Math.sqrt(variance);
}

function arrMedian(a: number[]): number {
  if (a.length === 0) return NaN;
  const sorted = [...a].sort((x, y) => x - y);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1]! + sorted[mid]!) / 2
    : sorted[mid]!;
}

function arrQuantile(a: number[], p: number): number {
  if (a.length === 0) return NaN;
  const sorted = [...a].sort((x, y) => x - y);
  const pos = p * (sorted.length - 1);
  const lo = Math.floor(pos);
  const hi = Math.ceil(pos);
  if (lo === hi) return sorted[lo]!;
  return sorted[lo]! * (hi - pos) + sorted[hi]! * (pos - lo);
}

function pearsonCorrArr(x: number[], y: number[]): number {
  const n = x.length;
  if (n < 2) return NaN;
  const mx = arrMean(x);
  const my = arrMean(y);
  let num = 0, dx2 = 0, dy2 = 0;
  for (let i = 0; i < n; i++) {
    const dx = x[i]! - mx;
    const dy = y[i]! - my;
    num += dx * dy;
    dx2 += dx * dx;
    dy2 += dy * dy;
  }
  const denom = Math.sqrt(dx2 * dy2);
  return denom < 1e-14 ? NaN : num / denom;
}

// ── Matrix comparison ────────────────────────────────────────────────────────

/** Flatten n×n matrix in column-major order (same as R's as.vector). */
function flattenColMajor(w: TNA['weights']): number[] {
  const n = w.rows;
  const out: number[] = [];
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      out.push(w.get(i, j));
    }
  }
  return out;
}

/**
 * Compare two TNA weight matrices using all 22 metrics.
 * Matches R's tna:::compare_ output exactly.
 */
export function compareWeightMatrices(a: TNA, b: TNA): Record<string, number> {
  const nanResult: Record<string, number> = {};
  for (const m of RELIABILITY_METRICS) nanResult[m.key] = NaN;

  if (a.labels.length !== b.labels.length) return nanResult;

  const n = a.labels.length;
  if (n === 0) return nanResult;

  const xv = flattenColMajor(a.weights);
  const yv = flattenColMajor(b.weights);
  const m2 = xv.length;

  const absX    = xv.map(v => Math.abs(v));
  const absY    = yv.map(v => Math.abs(v));
  const absDiff = xv.map((v, i) => Math.abs(v - yv[i]!));

  const meanX  = arrMean(xv);
  const meanY  = arrMean(yv);
  const stdX   = arrStd(xv);
  const stdY   = arrStd(yv);
  const meanAY = arrMean(absY);

  // Deviations
  const mad        = arrMean(absDiff);
  const median_ad  = arrMedian(absDiff);
  const rmsd       = Math.sqrt(arrMean(absDiff.map(d => d * d)));
  const max_ad     = Math.max(...absDiff);
  const rel_mad    = meanAY > 1e-14 ? mad / meanAY : NaN;
  const cv_ratio   = (Math.abs(meanX) > 1e-14 && Math.abs(stdY) > 1e-14)
    ? (stdX * meanY) / (meanX * stdY)
    : NaN;

  // Correlations
  const pearson  = pearsonCorrArr(xv, yv);
  const spearman = spearmanCorrArr(xv, yv);
  const kendall  = kendallTau(xv, yv);
  const dcor     = distanceCorr(xv, yv);

  // Dissimilarities
  const euclidean = Math.sqrt(absDiff.reduce((s, d) => s + d * d, 0));
  const manhattan = absDiff.reduce((s, d) => s + d, 0);

  let canberraSum = 0;
  for (let i = 0; i < m2; i++) {
    if (absX[i]! > 0 && absY[i]! > 0) {
      canberraSum += absDiff[i]! / (absX[i]! + absY[i]!);
    }
  }
  const canberra = canberraSum;

  const sumAbsXY = absX.reduce((s, v, i) => s + v + absY[i]!, 0);
  const braycurtis = sumAbsXY > 1e-14 ? manhattan / sumAbsXY : 0;

  const frobenius = Math.sqrt(n / 2) > 1e-14
    ? euclidean / Math.sqrt(n / 2)
    : NaN;

  // Similarities
  let dotXY = 0, dotXX = 0, dotYY = 0;
  for (let i = 0; i < m2; i++) {
    dotXY += xv[i]! * yv[i]!;
    dotXX += xv[i]! * xv[i]!;
    dotYY += yv[i]! * yv[i]!;
  }
  const cosine = Math.sqrt(dotXX * dotYY) > 1e-14
    ? dotXY / Math.sqrt(dotXX * dotYY)
    : NaN;

  let minSum = 0, maxSum = 0, sumAbsX = 0, sumAbsY = 0;
  for (let i = 0; i < m2; i++) {
    minSum  += Math.min(absX[i]!, absY[i]!);
    maxSum  += Math.max(absX[i]!, absY[i]!);
    sumAbsX += absX[i]!;
    sumAbsY += absY[i]!;
  }
  const jaccard = maxSum > 1e-14 ? minSum / maxSum : NaN;
  const dice    = (sumAbsX + sumAbsY) > 1e-14 ? 2 * minSum / (sumAbsX + sumAbsY) : NaN;
  const overlap = Math.min(sumAbsX, sumAbsY) > 1e-14
    ? minSum / Math.min(sumAbsX, sumAbsY)
    : NaN;

  const rv = rvCoefficient(a.weights, b.weights);

  // Pattern
  let matchCount = 0, totalDiff = 0;
  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n; j++) {
      const dA = a.weights.get(i + 1, j) - a.weights.get(i, j);
      const dB = b.weights.get(i + 1, j) - b.weights.get(i, j);
      if (Math.sign(dA) === Math.sign(dB)) matchCount++;
      totalDiff++;
    }
  }
  const rank_agree = totalDiff > 0 ? matchCount / totalDiff : NaN;

  const sameSign  = xv.filter((v, i) => Math.sign(v) === Math.sign(yv[i]!)).length;
  const sign_agree = m2 > 0 ? sameSign / m2 : NaN;

  return {
    mad, median_ad, rmsd, max_ad, rel_mad, cv_ratio,
    pearson, spearman, kendall, dcor,
    euclidean, manhattan, canberra, braycurtis, frobenius,
    cosine, jaccard, dice, overlap, rv,
    rank_agree, sign_agree,
  };
}

// ── Builder map ──────────────────────────────────────────────────────────────

const BUILDERS: Record<string, (data: SequenceData, opts: Record<string, unknown>) => TNA> = {
  tna:  (d, o) => tna(d as any, o as any),
  ftna: (d, o) => ftna(d as any, o as any),
  ctna: (d, o) => ctna(d as any, o as any),
  atna: (d, o) => atna(d as any, o as any),
};

// ── Main function ────────────────────────────────────────────────────────────

/**
 * Perform split-half reliability analysis.
 *
 * Repeatedly splits the sequence data into two halves, builds a model on
 * each half, and compares the resulting weight matrices using 22 metrics
 * that exactly match R's tna:::compare_ output.
 */
// ── Nestimate parity: networkReliability ─────────────────────────────────────
//
// Port of Nestimate::network_reliability (R/reliability.R, 0.4.4).
//
// Key behavioural identities mirrored from R:
//   - Metric set: 4 fields per iteration {mean_dev, median_dev, cor, max_dev}
//     (R's `.split_half_metrics`). These map to tnaj's 22-metric keys as
//     mad↔mean_dev, median_ad↔median_dev, pearson↔cor, max_ad↔max_dev.
//   - Half-A size via `round(n_seq * split)`, at least 1 (R: `max(1L, round(...))`).
//   - Diagonal is included in the flattened vector (matches R's `as.vector(mat)`).
//   - `scale` mirrors R's `.scale_matrix` exactly (per-iteration, applied to each
//     half before metric computation; preserves zero-range fallback).
//   - Summary is `{mean, sd}` per (model, metric) — sd with ddof=1, NAs ignored.
//   - If `sd(vec) == 0` on either half, `cor` is NaN (R returns NA_real_).
//   - Multi-model dispatch: array OR record; unnamed auto-name by model.type
//     (R auto-names by `$method`); duplicate names get `_1`, `_2` suffixes
//     (mirrors R's `make.unique(sep = "_")`).
//   - When `replayIndices` is provided, bypass RNG and use the given half-A
//     indices per iteration — this is how the R-parity verify harness reaches
//     pointwise agreement across PRNGs (see design spec §5.4).
//
// NOTE: this function is ADDITIVE. It does not replace the 22-metric
// `reliabilityAnalysis`; the two coexist as documented in the design spec.

export type ReliabilityScale = 'none' | 'minmax' | 'standardize' | 'proportion';

export interface NetworkReliabilityOptions {
  iter?: number;
  /** Fraction assigned to half A (default 0.5). 0 < split < 1. */
  split?: number;
  /** Cross-method scaling applied per iteration to each half matrix. */
  scale?: ReliabilityScale;
  seed?: number;
  /**
   * Optional per-iteration replay. Shape: number[iter][n_half_A]. When
   * provided, RNG sampling is skipped and these indices are used verbatim.
   * Only applies to the transition fast path; supplying replayIndices for a
   * model whose shape doesn't match will throw.
   *
   * Multi-model call: replayIndices map keyed by model name.
   */
  replayIndices?: number[][] | Record<string, number[][]>;
}

export interface NetworkReliabilityIterations {
  mean_dev: number[];
  median_dev: number[];
  cor: number[];
  max_dev: number[];
}

export interface NetworkReliabilitySummaryRow {
  model: string;
  metric: 'mean_dev' | 'median_dev' | 'cor' | 'max_dev';
  mean: number;
  sd: number;
}

export interface NetworkReliabilityResult {
  iterations: Record<string, NetworkReliabilityIterations>;
  summary: NetworkReliabilitySummaryRow[];
  models: string[];
  iter: number;
  split: number;
  scale: ReliabilityScale;
}

/** R's `round(x)` uses "round half to even". Banker's rounding. */
function rRound(x: number): number {
  const floor = Math.floor(x);
  const diff = x - floor;
  if (diff < 0.5) return floor;
  if (diff > 0.5) return floor + 1;
  // exactly 0.5 → round to even
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Apply `.scale_matrix` (R/reliability.R) — operates on a flattened vector.
 * Returns a new Float64Array. Zero-range / zero-sd / zero-total cases
 * return the input unchanged, matching R.
 */
function scaleVector(
  vec: Float64Array,
  method: ReliabilityScale,
): Float64Array {
  if (method === 'none') return vec;
  const n = vec.length;
  if (n === 0) return vec;

  if (method === 'minmax') {
    let min = Infinity;
    let max = -Infinity;
    for (let i = 0; i < n; i++) {
      const v = vec[i]!;
      if (v < min) min = v;
      if (v > max) max = v;
    }
    if (min === max) return vec;
    const span = max - min;
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) out[i] = (vec[i]! - min) / span;
    return out;
  }

  if (method === 'standardize') {
    let sum = 0;
    for (let i = 0; i < n; i++) sum += vec[i]!;
    const mean = sum / n;
    // sd with ddof=1 (matches stats::sd)
    let ss = 0;
    for (let i = 0; i < n; i++) {
      const d = vec[i]! - mean;
      ss += d * d;
    }
    const sd = n > 1 ? Math.sqrt(ss / (n - 1)) : 0;
    if (sd === 0) return vec;
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) out[i] = (vec[i]! - mean) / sd;
    return out;
  }

  if (method === 'proportion') {
    let total = 0;
    for (let i = 0; i < n; i++) total += vec[i]!;
    if (total === 0) return vec;
    const out = new Float64Array(n);
    for (let i = 0; i < n; i++) out[i] = vec[i]! / total;
    return out;
  }

  return vec;
}

/**
 * .split_half_metrics (R/reliability.R): 4 metrics on two matrices.
 * Operates on flattened column-major vectors (as.vector in R == column-major).
 */
function splitHalfMetrics(
  vecA: Float64Array,
  vecB: Float64Array,
): { mean_dev: number; median_dev: number; cor: number; max_dev: number } {
  const n = vecA.length;
  // Compute diffs + accumulate sums simultaneously
  const diffs = new Float64Array(n);
  let maxD = 0;
  let sumD = 0;
  for (let i = 0; i < n; i++) {
    const d = Math.abs(vecA[i]! - vecB[i]!);
    diffs[i] = d;
    if (d > maxD) maxD = d;
    sumD += d;
  }
  const mean_dev = n > 0 ? sumD / n : NaN;
  const median_dev = medianF64(diffs);

  // R's cor(): returns NA when sd(vec) == 0 on either side.
  const sdA = sdF64(vecA);
  const sdB = sdF64(vecB);
  let cor: number;
  if (sdA === 0 || sdB === 0) {
    cor = Number.NaN;
  } else {
    // Pearson on full vectors
    let mA = 0;
    let mB = 0;
    for (let i = 0; i < n; i++) {
      mA += vecA[i]!;
      mB += vecB[i]!;
    }
    mA /= n;
    mB /= n;
    let num = 0;
    let dx2 = 0;
    let dy2 = 0;
    for (let i = 0; i < n; i++) {
      const dx = vecA[i]! - mA;
      const dy = vecB[i]! - mB;
      num += dx * dy;
      dx2 += dx * dx;
      dy2 += dy * dy;
    }
    const denom = Math.sqrt(dx2 * dy2);
    cor = denom < 1e-14 ? Number.NaN : num / denom;
  }

  return { mean_dev, median_dev, cor, max_dev: maxD };
}

function medianF64(arr: Float64Array): number {
  if (arr.length === 0) return NaN;
  const sorted = Array.from(arr).sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1]! + sorted[mid]!) / 2
    : sorted[mid]!;
}

function sdF64(arr: Float64Array): number {
  const n = arr.length;
  if (n < 2) return 0;
  let sum = 0;
  for (let i = 0; i < n; i++) sum += arr[i]!;
  const mean = sum / n;
  let ss = 0;
  for (let i = 0; i < n; i++) {
    const d = arr[i]! - mean;
    ss += d * d;
  }
  return Math.sqrt(ss / (n - 1));
}

/** Column-major flatten: matches R's as.vector(). */
function flattenColMajorF64(m: TNA['weights']): Float64Array {
  const n = m.rows;
  const out = new Float64Array(n * n);
  let k = 0;
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      out[k++] = m.get(i, j);
    }
  }
  return out;
}

/**
 * Split-half reliability for a single TNA model.
 *
 * Parallels R's `.reliability_transition` path: reuses the same per-sequence
 * transition-count infrastructure (tnaj: `computeTransitions3D`) and derives
 * each half's weight matrix from the counts of the selected sequences.
 */
function singleModelReliability(
  model: TNA,
  iter: number,
  split: number,
  scale: ReliabilityScale,
  rng: SeededRNG,
  replayIndices: number[][] | null,
): NetworkReliabilityIterations {
  if (!model.data) {
    throw new Error(
      "networkReliability: model does not contain \$data. Rebuild with build_network().",
    );
  }
  const seqData = model.data;
  const n = seqData.length;
  if (n < 2) {
    throw new Error('networkReliability: need at least 2 sequences');
  }
  const nA = Math.max(1, rRound(n * split));
  if (nA < 1 || n - nA < 1) {
    throw new Error(
      `networkReliability: each split half must have at least 1 sequence (n=${n}, nA=${nA})`,
    );
  }

  // Pad sequences and precompute per-sequence transition 3-D stack.
  let maxLen = 0;
  for (const seq of seqData) if (seq.length > maxLen) maxLen = seq.length;
  const padded = seqData.map((seq) => {
    if (seq.length >= maxLen) return seq;
    const pad: (string | null)[] = new Array(maxLen - seq.length).fill(null);
    return [...seq, ...pad];
  });

  const trans = computeTransitions3D(padded, model.labels, model.type, model.params);
  const modelScaling = model.scaling.length > 0 ? model.scaling : null;

  const out: NetworkReliabilityIterations = {
    mean_dev: new Array(iter),
    median_dev: new Array(iter),
    cor: new Array(iter),
    max_dev: new Array(iter),
  };

  for (let it = 0; it < iter; it++) {
    let idxA: number[];
    if (replayIndices) {
      const replay = replayIndices[it];
      if (!replay) {
        throw new Error(
          `networkReliability: replayIndices[${it}] missing (iter=${iter}, have=${replayIndices.length})`,
        );
      }
      if (replay.length !== nA) {
        throw new Error(
          `networkReliability: replayIndices[${it}] has length ${replay.length}, expected ${nA}`,
        );
      }
      idxA = replay;
    } else {
      idxA = rng.choiceWithoutReplacement(n, nA);
    }
    const setA = new Set(idxA);
    const idxB: number[] = [];
    for (let k = 0; k < n; k++) if (!setA.has(k)) idxB.push(k);

    try {
      const transA = idxA.map((i) => trans[i]!);
      const transB = idxB.map((i) => trans[i]!);
      const matA = computeWeightsFrom3D(transA, model.type, modelScaling);
      const matB = computeWeightsFrom3D(transB, model.type, modelScaling);
      let vecA = flattenColMajorF64(matA);
      let vecB = flattenColMajorF64(matB);
      vecA = scaleVector(vecA, scale);
      vecB = scaleVector(vecB, scale);
      const m = splitHalfMetrics(vecA, vecB);
      out.mean_dev[it] = m.mean_dev;
      out.median_dev[it] = m.median_dev;
      out.cor[it] = m.cor;
      out.max_dev[it] = m.max_dev;
    } catch {
      out.mean_dev[it] = NaN;
      out.median_dev[it] = NaN;
      out.cor[it] = NaN;
      out.max_dev[it] = NaN;
    }
  }

  return out;
}

/** Summary row helper: mean + sd (ddof=1), NaN-aware. */
function summaryMeanSd(vals: number[]): { mean: number; sd: number } {
  const filtered = vals.filter((v) => Number.isFinite(v));
  if (filtered.length === 0) return { mean: NaN, sd: NaN };
  let s = 0;
  for (const v of filtered) s += v;
  const mean = s / filtered.length;
  if (filtered.length < 2) return { mean, sd: NaN };
  let ss = 0;
  for (const v of filtered) ss += (v - mean) * (v - mean);
  return { mean, sd: Math.sqrt(ss / (filtered.length - 1)) };
}

/** Deduplicate names R-style: append _1, _2, ... to collisions. */
function makeUnique(names: string[]): string[] {
  const seen: Record<string, number> = {};
  return names.map((nm) => {
    if (seen[nm] === undefined) {
      seen[nm] = 0;
      return nm;
    }
    seen[nm]++;
    return `${nm}_${seen[nm]}`;
  });
}

/**
 * Nestimate-parity split-half reliability across one or more TNA models.
 *
 * Mirrors Nestimate::network_reliability (R/reliability.R) with the
 * transition-model fast path (same semantics as
 * `.reliability_transition`). Returns 4 metrics per iteration — superset
 * of these is already available via `reliabilityAnalysis` (22 metrics).
 *
 * For R-parity under deterministic index replay, pass `replayIndices`.
 */
export function networkReliability(
  models: TNA | TNA[] | Record<string, TNA>,
  options: NetworkReliabilityOptions = {},
): NetworkReliabilityResult {
  const {
    iter = 1000,
    split = 0.5,
    scale = 'none',
    seed = 42,
    replayIndices,
  } = options;

  if (iter < 2) throw new Error('networkReliability: iter must be >= 2');
  if (!(split > 0 && split < 1)) {
    throw new Error('networkReliability: split must be in (0, 1)');
  }

  // Normalise input to a Record<string, TNA>
  let modelMap: Record<string, TNA>;
  let modelOrder: string[];
  if (Array.isArray(models)) {
    const names = models.map((m) => m.type);
    const unique = makeUnique(names);
    modelMap = {};
    for (let i = 0; i < models.length; i++) modelMap[unique[i]!] = models[i]!;
    modelOrder = unique;
  } else if (models && typeof models === 'object' && !(models as TNA).weights) {
    // Record<string, TNA>
    modelMap = models as Record<string, TNA>;
    modelOrder = Object.keys(modelMap);
  } else {
    // Single TNA
    const m = models as TNA;
    modelMap = { [m.type]: m };
    modelOrder = [m.type];
  }

  if (modelOrder.length === 0) {
    throw new Error('networkReliability: at least one model required');
  }

  const rng = new SeededRNG(seed);

  const iterations: Record<string, NetworkReliabilityIterations> = {};
  const summaryRows: NetworkReliabilitySummaryRow[] = [];

  for (const modelName of modelOrder) {
    const model = modelMap[modelName]!;
    let modelReplay: number[][] | null = null;
    if (replayIndices) {
      if (Array.isArray(replayIndices)) {
        if (modelOrder.length > 1) {
          throw new Error(
            'networkReliability: replayIndices as array requires single-model call; use Record<string, number[][]>',
          );
        }
        modelReplay = replayIndices;
      } else {
        modelReplay = replayIndices[modelName] ?? null;
        if (!modelReplay) {
          throw new Error(
            `networkReliability: replayIndices missing for model '${modelName}'`,
          );
        }
      }
    }

    const itsRes = singleModelReliability(
      model,
      iter,
      split,
      scale,
      rng,
      modelReplay,
    );
    iterations[modelName] = itsRes;

    for (const metric of ['mean_dev', 'median_dev', 'cor', 'max_dev'] as const) {
      const { mean, sd } = summaryMeanSd(itsRes[metric]);
      summaryRows.push({ model: modelName, metric, mean, sd });
    }
  }

  return {
    iterations,
    summary: summaryRows,
    models: modelOrder,
    iter,
    split,
    scale,
  };
}

// ── End of networkReliability ────────────────────────────────────────────────

export function reliabilityAnalysis(
  sequenceData: SequenceData,
  modelType: 'tna' | 'ftna' | 'ctna' | 'atna',
  opts: {
    iter?: number;
    split?: number;
    atnaBeta?: number;
    seed?: number;
    scaling?: string;
    addStartState?: boolean;
    startStateLabel?: string;
    addEndState?: boolean;
    endStateLabel?: string;
  } = {},
): ReliabilityResult {
  if (sequenceData.length < 4) {
    throw new Error('Need at least 4 sequences for reliability analysis');
  }

  const {
    iter = 100, split = 0.5, atnaBeta = 0.1, seed = 42,
    scaling, addStartState, startStateLabel, addEndState, endStateLabel,
  } = opts;
  const n  = sequenceData.length;
  const nA = Math.floor(n * split);

  if (nA < 2 || n - nA < 2) {
    throw new Error('Each split half must have at least 2 sequences');
  }

  const applyStartEnd = (seqs: SequenceData): SequenceData => {
    if (!addStartState && !addEndState) return seqs;
    return seqs.map(seq => {
      let last = seq.length - 1;
      while (last >= 0 && seq[last] === null) last--;
      const trimmed: (string | null)[] = seq.slice(0, last + 1);
      if (addStartState) trimmed.unshift(startStateLabel || 'Start');
      if (addEndState)   trimmed.push(endStateLabel   || 'End');
      return trimmed;
    });
  };

  const rng = new SeededRNG(seed);
  const builder = BUILDERS[modelType]!;
  const buildOpts: Record<string, unknown> = {};
  if (scaling)              buildOpts.scaling = scaling;
  if (modelType === 'atna') buildOpts.beta    = atnaBeta;

  const iterations: Record<string, number[]> = {};
  for (const m of RELIABILITY_METRICS) iterations[m.key] = [];

  for (let it = 0; it < iter; it++) {
    const indicesA = rng.choiceWithoutReplacement(n, nA);
    const setA = new Set(indicesA);
    const indicesB = Array.from({ length: n }, (_, i) => i).filter(i => !setA.has(i));

    const seqA: SequenceData = applyStartEnd(indicesA.map(i => sequenceData[i]!));
    const seqB: SequenceData = applyStartEnd(indicesB.map(i => sequenceData[i]!));

    try {
      const modelA = builder(seqA, buildOpts);
      const modelB = builder(seqB, buildOpts);
      const metrics = compareWeightMatrices(modelA, modelB);
      for (const m of RELIABILITY_METRICS) {
        iterations[m.key]!.push(metrics[m.key]!);
      }
    } catch {
      for (const m of RELIABILITY_METRICS) {
        iterations[m.key]!.push(NaN);
      }
    }
  }

  const summary: ReliabilityMetricSummary[] = RELIABILITY_METRICS.map(metDef => {
    const raw  = iterations[metDef.key] ?? [];
    const vals = raw.filter(v => isFinite(v));
    return {
      metric:   metDef.label,
      category: metDef.category,
      mean:     arrMean(vals),
      sd:       arrStd(vals),
      median:   arrMedian(vals),
      min:      vals.length > 0 ? Math.min(...vals) : NaN,
      max:      vals.length > 0 ? Math.max(...vals) : NaN,
      q25:      arrQuantile(vals, 0.25),
      q75:      arrQuantile(vals, 0.75),
    };
  });

  return { iterations, summary, iter, split, modelType };
}
